INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_fetchTheCountOfEndpoints', E'Fetch the total count of endpoints that match the given filter criteria.\nParams: profilingStatus, macAddress, macAddresses, ip, deviceType, hardwareManufacturer, hardwareModel, operatingSystem', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getListOfProfilingRules', E'This API fetches the list of profiling rules. It can be used to show profiling rules in client applications, or export those from an environment. ''POST /profiling-rules/bulk'' API can be used to import such exported rules into another environment.\nIf this API is used to export rules to be imported...\nParams: ruleType, includeDeleted, limit, offset, sortBy, order', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_createAProfilingRule', E'Creates profiling rule from the request body.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getTaskDetails', E'Fetches the details of backend task. Task is typically created by making call to some other API that takes longer time to execute.\nParams: taskId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getDetailsOfASingleProfilingRule', E'Fetches details of the profiling rule for the given ''ruleId''.\nParams: ruleId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_deleteAnExistingProfilingRule', E'Deletes the profiling rule for the given ''ruleId''.\nParams: Content-Type (required), ruleId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updateAnExistingProfilingRule', E'Updates the profiling rule for the given ''ruleId''.\nParams: Content-Type (required), ruleId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getAIEndpointAnalyticsAttributeDictionaries', E'Fetches the list of attribute dictionaries.\nParams: includeAttributes', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_applyANCPolicy', E'Applies given ANC policy to the endpoint.\nParams: Content-Type (required), epId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_revokeANCPolicy', E'Revokes given ANC policy from the endpoint.\nParams: epId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getEndpointDetails', E'Fetches details of the endpoint for the given unique identifier ''epId''.\nParams: epId (required), include', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_deleteAnEndpoint', E'Deletes the endpoint for the given unique identifier ''epId''.\nParams: epId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updateARegisteredEndpoint', E'Update attributes of a registered endpoint.\nParams: Content-Type (required), epId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getCountOfProfilingRules', E'This API fetches the count of profiling rules based on the filter values provided in the query parameters. The filter parameters are same as that of ''GET /profiling-rules'' API, excluding the pagination and sort parameters.\nParams: ruleType, includeDeleted', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_importProfilingRulesInBulk', E'This API imports the given list of profiling rules. For each record,\n1) If ''ruleType'' for a record is not ''Custom Rule'', then it is rejected.\n2) If ''ruleId'' is provided in the input record,\n  2a) Record with same ''ruleId'' exists in the system, then it is replaced with new data.\n  2b) Record with ...\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_registerAnEndpoint', E'Register a new endpoint in the system.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_queryTheEndpoints', E'Query the endpoints, optionally using various filter and pagination criteria. ''GET /endpoints/count'' API can be used to find out the total number of endpoints matching the filter criteria.\nParams: profilingStatus, macAddress, macAddresses, ip, deviceType, hardwareManufacturer, hardwareModel, operatingSystem', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getANCPolicies', E'Fetches the list of ANC policies available in ISE.', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_processCMDBEndpoints', E'Processes incoming CMDB endpoints data and imports the same in AI Endpoint Analytics.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_threatSummary', E'The Threat Summary for the Rogues and aWIPS\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getThreatTypes', E'Intent API to fetch all threat types defined.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getAllowedMacAddress', E'Intent API to fetch all the allowed mac addresses in the system.\nParams: Content-Type (required), offset, limit', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_addAllowedMacAddress', E'Intent API to add the threat mac address to allowed list.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_rogueAdditionalDetails', E'This API provides additional information of the rogue threats with details at BSSID level. The additional information includes Switch Port details in case of Rogue on Wire, first time when the rogue is seen in the network etc.', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_rogueAdditionalDetailCount', E'This API returns the count for the Rogue Additional Details.', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_wirelessRogueAPContainmentStatus', E'Intent API to check the wireless rogue access point containment status. The response includes all the details like containment status, contained by WLC, containment status of each BSSID etc. This API also includes the information of strongest detecting WLC for this rogue access point.\nParams: Content-Type (required), macAddress (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getThreatLevels', E'Intent API to fetch all threat levels defined.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getAllowedMacAddressCount', E'Intent API to fetch the count of allowed mac addresses in the system.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_threatDetails', E'The details for the Rogue and aWIPS threats\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_startWirelessRogueAPContainment', E'Intent API to start the wireless rogue access point containment. This API will initiate the containment operation on the strongest detecting WLC for the given Rogue AP. This is a resource intensive operation which has legal implications since the rogue access point on whom it is triggered, might ...\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_stopWirelessRogueAPContainment', E'Intent API to stop the wireless rogue access point containment. This API will stop the containment through single WLC. The response includes the details like WLC and BSSID on which the stop containment has been initiated.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_disasterRecoveryOperationalStatus', E'Returns the status of Disaster Recovery operation performed on the system.', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_removeAllowedMacAddress', E'Intent API to remove the threat mac address from allowed list.\nParams: Content-Type (required), macAddress (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_threatDetailCount', E'The details count for the Rogue and aWIPS threats\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_retrievesCiscoIMCConfigurationsForCatalystCenterNodes', E'This API retrieves the configurations of the Cisco Integrated Management Controller (IMC) that have been added to the Catalyst Center nodes.\n\nThe Cisco IMC configuration APIs enable the management of connections between Cisco IMC and Cisco Catalyst Center. By providing the Cisco IMC IP address an...', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_addsCiscoIMCConfigurationToACatalystCenterNode', E'This API adds a Cisco Integrated Management Controller (IMC) configuration to a Cisco Catalyst Center node, identified by its `nodeId`. Obtain the `nodeId` from the `id` attribute in the response of the `/dna/intent/api/v1/nodes-config` API.\n\nThe Cisco IMC configuration APIs enable the managemen...\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_assignNetworkDeviceProductNameToTheGivenSoftwareImage', E'Assign network device product name and sites for the given image identifier. Refer `/dna/intent/api/v1/images` API for obtaining imageId\nParams: Content-Type (required), imageId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('retrievesNetworkDeviceProductNamesAssignedToASoftwareImage.', E'Returns a list of network device product names and associated sites for a given image identifier. Refer `/dna/intent/api/v1/images` API for obtaining `imageId`.\nParams: imageId (required), productName, productId, recommended, assigned, offset, limit', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('getTrendAnalyticsDataOfAAAServicesForGivenSetOfComplexFilters.', E'Gets the trend analytics data related to AAA Services based on given filters and group by field. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api-specs/blob/main/Assurance/CE_...\nParams: Content-Type (required), X-CALLER-ID', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_disasterRecoveryStatus', E'Detailed and Summarized status of DR components (Active, Standby and Witness system''s health).', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('theTrendAnalyticsDataForTheNetworkDeviceInTheSpecifiedTimeRange', E'The Trend analytics data for the network Device in the specified time range. The data is grouped based on the trend time Interval, other input parameters like attribute and aggregate attributes. For detailed information about the usage of the API, please refer to the Open API specification docume...\nParams: Content-Type (required), id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('createsATrialForSecurityAdvisoriesDetectionOnNetworkDevices', E'Creates a trial for security advisories detection on network devices. The consent to connect agreement must have been accepted in the UI for this to succeed. Please refer to the user guide at <https://www.cisco.com/c/en/us/support/cloud-systems-management/dna-center/products-user-guide-list.html>...', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('getTrialDetailsForSecurityAdvisoriesDetectionOnNetworkDevices', E'Get trial details for security advisories detection on network devices', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_createSSID', E'This API allows the user to create an SSID (Service Set Identifier) at the Global site\nParams: Content-Type (required), siteId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getSSIDBySite', E'This API allows the user to get all SSIDs (Service Set Identifier) at the given site\nParams: siteId (required), limit, offset, ssid, wlanType, authType, l3authType', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getFabricDevicesLayer2HandoffsCount', E'Returns the count of layer 2 handoffs of fabric devices that match the provided query parameters.\nParams: fabricId (required), networkDeviceId', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_configureAccessPointsV1', E'User can configure multiple access points with required options using this intent API.\nThis API does not support configuration of CleanAir or SI for IOS-XE devices with version greater than or equal to 17.9\nParams: Content-Type', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_addMulticastVirtualNetworks', E'Adds multicast for virtual networks based on user input.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getMulticastVirtualNetworks', E'Returns a list of multicast configurations for virtual networks that match the provided query parameters.\nParams: fabricId, virtualNetworkName, offset, limit', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updateMulticastVirtualNetworks', E'Updates multicast configurations for virtual networks based on user input.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_retrievesDiagnosticTaskByID', E'This API retrieves the diagnostic task identified by the specified `id`.\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_enableApplicationTelemetryFeatureOnMultipleNetworkDevices', E'This API can be used to enable application telemetry feature on multiple network devices.\nRequest payload should include the list of network devices where application telemetry\nhas to be enabled. For wireless controllers, it also needs the WLAN modes / SSID details\nto be included for enablement.\n...\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_addMembersToTheTag', E'Adds members to the tag specified by id\nParams: Content-Type (required), id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getTagMembersById', E'Returns tag members specified by id\nParams: id (required), memberType (required), offset, limit, memberAssociationType, level', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_discardsTheICAPConfigurationIntentByActivityID.', E'Discard the ICAP configuration intent by activity ID, which was returned in TaskResponse''s property "taskId" at the beginning of the preview-approve workflow.  Discarding the intent can only be applied to intent activities that have not been deployed.\n\nNote that ICAP type FULL, ONBOARDING, OTA, a...\nParams: previewActivityId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_retrievePortChannelsCountForANetworkDevice.', E'This API endpoint retrieves the count of port channels for the given network device.\nParams: networkDeviceId (required), id, name', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getApplicationSet/s', E'Get application set/s by offset/limit or by name\nParams: attributes (required), name, offset (required), limit (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_createApplicationSet/s', E'Create new custom application set/s\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_submitRequestToCountSitesEnergyFromQuery', E'Submits a request to retrieve the total count of sites that provide energy data, filtered according to the specified query parameters. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-ce...\nParams: Content-Type (required), X-CALLER-ID, taskId', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_countSitesEnergyForTheGivenTaskID', E'Gets count sites energy task result for the given task ID. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api-specs/blob/main/Assurance/CE_Cat_Center_Org-sitesEnergy-1.0.1-resol...\nParams: X-CALLER-ID, taskId', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_returnsTheCountOfNetworkDeviceProductNamesForASite', E'Returns the count of network device product names for given filters. The default value of `siteId` is global.\nParams: siteId, productName', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getViewsForAGivenViewGroup', E'Gives a list of summary of all views in a viewgroup. Use "Get all view groups" API to get the viewGroupIds (required as a query param for this API) for available viewgroups.\nParams: viewGroupId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getsAllTheVersionsOfAGivenTemplate', E'Get all the versions of template by its id\nParams: templateId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getTheTotalNumberOfIssuesForGivenSetOfFilters', E'Returns the total number issues for given set of filters. If there is no start and/or end time, then end time will be defaulted to current time and start time will be defaulted to 24-hours ago from end time. https://github.com/cisco-en-programmability/catalyst-center-api-specs/blob/main/Assurance...\nParams: X-CALLER-ID, startTime, endTime, isGlobal, priority, severity, status, entityType', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_countsIPAddressSubpools.', E'Counts IP address subpools, which reserve address space from a global pool (or global pools).\nParams: siteId', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_removeALinkFromPortChannel', E'This API removes a member link from an existing Port Channel, reverting the link to a P2P L3 interface.\nParams: Content-Type (required), id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updatesABuilding', E'Updates a building in the network hierarchy.\nParams: Content-Type (required), id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_deletesABuilding', E'Deletes building in the network hierarchy. This operations fails if there are any floors for this building, or if there are any devices assigned to this building.\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getsABuilding', E'Gets a building in the network hierarchy.\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getCountOfAllDiscoveryJobs', E'Returns the count of all available discovery jobs', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getAnchorGroupByID', E'This API allows the user to get an AnchorGroup by AnchorGroup ID\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updateAnchorGroup', E'This API allows the user to update an AnchorGroup\nParams: Content-Type (required), id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_deleteAnchorGroupByID', E'This API allows the user to delete an AnchorGroup  by specifying the AnchorGroup ID\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updateWebhookDestination', E'Update Webhook Destination\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
