INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_createMaintenanceScheduleForNetworkDevices', E'API to create maintenance schedule for network devices. The state of network device can be queried using API `GET /dna/intent/api/v1/networkDevices`. The `managementState` attribute of the network device will be updated to `UNDER_MAINTENANCE` when the maintenance window starts.', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
