INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_deletesTheCiscoIMCConfigurationForACatalystCenterNode', E'This API removes a specific Cisco Integrated Management Controller (IMC) configuration from a Catalyst Center node using the provided identifier.\n\nThe Cisco IMC configuration APIs enable the management of connections between Cisco IMC and Cisco Catalyst Center. By providing the Cisco IMC IP addre...\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updatesTheCiscoIMCConfigurationForACatalystCenterNode', E'This API updates the Cisco Integrated Management Controller (IMC) configuration for a Catalyst Center node, identified by the specified ID.\n\nThe Cisco IMC configuration APIs enable the management of connections between Cisco IMC and Cisco Catalyst Center. By providing the Cisco IMC IP address and...\nParams: Content-Type (required), id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
