INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_add,UpdateOrRemoveSSIDMappingToAVLAN', E'Add, update, or remove SSID mappings to a VLAN. If the payload doesn''t contain a ''vlanName'' which has SSIDs mapping done earlier then all the mapped SSIDs of the ''vlanName'' is cleared. The request must include all SSIDs currently mapped to a VLAN, as determined by the response from the GET operat...\nParams: Content-Type (required), fabricId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
