INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_unassignNetworkDevicesFromSites', E'Unassign unprovisioned network devices from their site. If device controllability is enabled, it will be triggered once device unassigned from site successfully. Device Controllability can be enabled/disabled using `/dna/intent/api/v1/networkDevices/deviceControllability/settings`.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('retrievesTheListOfNetworkApplicationsAlongWithExperienceAndHealt', E'Retrieves the list of network applications along with experience and health metrics. If startTime and endTime are not provided, the API defaults to the last 24 hours. `siteId` is mandatory. `siteId` must be a site UUID of a building. For detailed information about the usage of the API, please ref...\nParams: X-CALLER-ID, startTime, endTime, limit, offset, sortBy, order, siteId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
