INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getIssueTriggerDefinitionForGivenId.', E'Get system issue defintion for the given id. Definition includes all properties from IssueTriggerDefinition schema by default. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api...\nParams: X-CALLER-ID, id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
