INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getPowerProfileByID', E'This API allows the user to get a Power Profile by Power Profile ID that captured in wireless settings design\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
