INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_assignANetworkProfileForSitesToTheGivenSite', E'Assigns a given network profile for sites to a given site. Also assigns the profile to child sites.\nParams: Content-Type (required), profileId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_createEventDrivenRRMConfigurationFeatureTemplate', E'This API allows users to create a Event Driven RRM configuration feature template.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getNetworkDevicesCredentialsSyncStatus', E'Get network devices credentials sync status at a given site.\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getAPAuthorizationListByID', E'This API allows the user to get an AP Authorization List by AP Authorization List ID that captured in wireless settings design.\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
