INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_deleteAPAuthorizationList', E'This API allows the user to delete an AP Authorization List.\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
