INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_setBannerSettingsForASite', E'Set banner settings for a site; `null` values indicate that the setting will be inherited from the parent site; empty objects (`{}`) indicate that the settings is unset.\nParams: Content-Type (required), id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
