INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updateITSMIntegrationSetting', E'Updates the ITSM Integration setting\nParams: instanceId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
