INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_createsATrialForBugsDetectionOnNetworkDevices', E'Creates a trial for bugs detection on network devices. The consent to connect agreement must have been accepted in the UI for this to succeed. Please refer to the user guide at <https://www.cisco.com/c/en/us/support/cloud-systems-management/dna-center/products-user-guide-list.html> for more detai...', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_aPProvision', E'This API is used to provision Access Points. Prerequisite: Access Point has to be assigned to the site using the API /dna/intent/api/v1/networkDevices/assignToSite/apply.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_queryNetworkDevicesWithFilters', E'Returns the list of network devices, determined by the filters.\nIt is possible to filter the network devices based on various parameters, such as device type, device role, software version, etc. The API returns a paginated response based on ''limit'' and ''offset'' parameters, allowing up to 500 reco...\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_retrievesTheCountOfMRPRings.', E'This API returns the count of MRP rings for the given fields - networkDeviceId (Network device ID of the MRP ring member. The networkDeviceId is the instanceUuid attribute in the response of API - /dna/intent/api/v1/networkDevices).\nParams: networkDeviceId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getPortChannelInformationById', E'This API retrieves Port Channel information using its ID.\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_deletePortChannel', E'This API deletes a Port Channel between LAN Automation associated devices using a valid Port Channel ID.\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
