INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('updateADevice(s)TelemetrySettingsToConformToTheTelemetrySettings', E'Update a device(s) telemetry settings to conform to the telemetry settings for its site.  One Task is created to track the update, for more granular status tracking, split your devices into multiple requests.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
