INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_retrievesTheListOfValidationWorkflows', E'Retrieves the workflows that have been successfully submitted and are currently available. This is sorted by `submitTime`\nParams: startTime, endTime, runStatus, offset, limit', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
