INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_returnsAllIssueTriggerDefinitionsForGivenFilters.', E'Get all system issue defintions. The supported filters are id, name, profileId and definition enable status. An issue trigger definition can be different across the profile and device type. So, `profileId` and `deviceType` in the query param is important and default is global profile and all devi...\nParams: X-CALLER-ID, deviceType, profileId, id, name, priority, issueEnabled, attribute', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_lANAutomationDeviceUpdate', E'Invoke this API to perform a DAY-N update on LAN Automation-related devices. Supported features include Loopback0 IP update, hostname update, link addition, and link deletion.\nParams: Content-Type (required), feature (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updateHealthScoreDefinitions.', E'Update health thresholds, include status of overall health status for each metric.\n\nAnd also to synchronize with global profile issue thresholds of the definition for given metric. For detailed information about the usage of the API, please refer to the Open API specification document - https://g...\nParams: Content-Type (required), X-CALLER-ID', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
