INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('theTrendAnalyticsDataForThousandEyesTestResultsInTheSpecifiedTim', E'Get trend time series for ThousandEyes test results.\n\nThe data will be grouped based on the specified trend time interval. If `startTime` and `endTime` are not provided, the API defaults to the last 24 hours.\n\nBy default the number of records returned will be 100 and the records will be sorted by...\nParams: X-CALLER-ID, siteId, startTime, endTime, trendInterval, testId, testName, testType', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_addVirtualAccount', E'Registers a Smart Account, Virtual Account and the relevant server profile info with the PnP System & database. The devices present in the registered virtual account are synced with the PnP database as well. The response payload returns the new profile\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
