INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getDeviceList', E'Returns list of network devices based on filter criteria such as management IP address, mac address, hostname, etc. You can use the .* in any value to conduct a wildcard search.\nFor example, to find all hostnames beginning with myhost in the IP address range 192.25.18.n, issue the following reque...\nParams: hostname, managementIpAddress, macAddress, locationName, serialNumber, location, family, type', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
