INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updateDeviceDetails', E'Update the credentials, management IP address of a given device (or a set of devices) in Catalyst Center and trigger an inventory sync.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
