INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_returnsPOEInterfaceDetailsForTheDevice.', E'Returns POE interface details for the device, where deviceuuid is mandatory & accepts comma seperated interface names which is optional and returns information for that particular interfaces where(operStatus = operationalStatus)\nParams: deviceUuid (required), interfaceNameList', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_queryAssuranceEvents', E'Returns the list of events discovered by Catalyst Center, determined by the complex filters. Please refer to the ''API Support Documentation'' section to understand which fields are supported. For detailed information about the usage of the API, please refer to the Open API specification document -...\nParams: X-CALLER-ID, deviceFamily (required), startTime, endTime, messageType, severity, siteId, siteHierarchyId', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updateAPPnPLocationSetting', E'Enable or disable the AP PnP Location setting in the system.Once the AP PnP Location Setting is enabled, the Access Point''s assigned Site name will be configured as the AP Location during the PnP Claim process. This applies only during the PnP onboarding process and not during any subsequent prov...', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
