INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_deregisterVirtualAccount', E'Deregisters the specified smart account & virtual account info and the associated device information from the PnP System & database. The devices associated with the deregistered virtual account are removed from the PnP database as well. The response payload contains the deregistered smart & virtu...\nParams: domain (required), name (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
