INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_taggingGoldenImage', E'Creates golden image tagging specifically for a particular device type or supervisor engine module.\nConditions for tagging the golden image:\n\n1) The golden tagging of SMU, PISRT_SMU, APSP, and APDP image type depends on the golden tagged applied on the base image. If any discrepancies are identif...\nParams: Content-Type (required), id (required), siteId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
