INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_get802.11beProfiles', E'This API allows the user to get 802.11be Profile(s) configured under Wireless Settings\nParams: limit, offset, profileName, isOfDmaDownLink, isOfDmaUpLink, isMuMimoUpLink, isMuMimoDownLink, isOfDmaMultiRu', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_createA802.11beProfile', E'This API allows the user to create a 802.11be Profile.Catalyst Center will push this profile to device''s "default-dot11be-profile”.Also please note , 802.11be Profile is supported only on IOS-XE controllers since device version 17.15\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updateGlobalResyncInterval', E'Updates the resync interval (in minutes) globally for devices which do not have custom resync interval. To override this setting for all network devices refer to [/networkDevices/resyncIntervalSettings/override]', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
