INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_attachAListOfNetworkProfilesToADay-NCLITemplate', E'Attaches a list of network profiles to the Day-N CLI template by passing the profile IDs and template ID.\nParams: Content-Type (required), templateId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_detachAListOfNetworkProfilesFromADay-NCLITemplate', E'Detach a list of network profiles from a Day-N CLI template with a list of profile IDs along with the template ID.\nParams: templateId (required), profileId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
