INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getSecurityAdvisoriesAffectingTheNetworkDevice', E'Get security advisories affecting the network device\nParams: networkDeviceId (required), id, cvssBaseScore, securityImpactRating, offset, limit, sortBy, order', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
