INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_submitRequestForSiteAnalyticsTrendData', E'Submits the task to get site analytics trend data for a given site. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api-specs/blob/main/Assurance/CE_Cat_Center_Org-SiteKpiSummari...\nParams: Content-Type (required), X-CALLER-ID', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getSiteAnalyticsTrendDataForTheGivenTaskId', E'Gets site analytics trend data for the given task id. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api-specs/blob/main/Assurance/CE_Cat_Center_Org-SiteKpiSummaries-1.0.0-resol...\nParams: X-CALLER-ID, taskId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getEmailSubscriptionDetails', E'Gets the list of subscription details for specified connectorType\nParams: name, instanceId, offset, limit, sortBy, order', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getCountOfNetworkBugDevicesForTheBug', E'Get count of network bug devices for the bug\nParams: id (required), networkDeviceId, scanMode, scanStatus', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getAllKeywordsOfCLIsAcceptedByCommandRunner', E'Get valid keywords', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getBackupById', E'This api is used to get a specific backup based on the provided `backup id`.\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_deleteBackup', E'This api is used to trigger delete workflow of a specific backup based on the provided `id`\nObtain the `id` from the id attribute in the response of the `/dna/system/api/v1/backups` API.\nTo monitor the progress and completion of the backup deletion , please call `/dna/system/api/v1/backupRestoreE...\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_countTheNumberOfEvents', E'API to fetch the count of assurance events that match the filter criteria. Please refer to the ''API Support Documentation'' section to understand which fields are supported. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.co...\nParams: X-CALLER-ID, deviceFamily (required), startTime, endTime, messageType, severity, siteId, siteHierarchyId', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_setAAASettingsForASite', E'Set AAA settings for a site; `null` values indicate that the settings will be inherited from the parent site; empty objects (`{}`) indicate that the settings is unset.\nParams: Content-Type (required), id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_retrieveAAASettingsForASite', E'Retrieve AAA settings for a site; `null` values indicate that the setting will be inherited from the parent site; empty objects (`{}`) indicate that the setting is unset at a site.\nParams: id (required), _inherited', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_queryAnAggregatedSummaryOfSiteHealthData.', E'Query an aggregated summary of all site health\nThis API provides the latest health data from a given `endTime`\nIf data is not ready for the provided endTime, the request will fail, and the error message will indicate the recommended endTime to use to retrieve a complete data set.\nThis behavior ma...\nParams: Content-Type (required), X-CALLER-ID, siteHierarchy, siteHierarchyId, siteType, id', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_readAnAggregatedSummaryOfSiteHealthData.', E'Get an aggregated summary of all site health or use the query params to get an aggregated summary of health for a subset of sites.\nThis API provides the latest health data from a given `endTime`\nIf data is not ready for the provided endTime, the request will fail, and the error message will indic...\nParams: X-CALLER-ID, startTime, endTime, siteHierarchy, siteHierarchyId, siteType, id, view', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getExtranetPolicyCount', E'Returns the count of extranet policies that match the provided query parameters.', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('getsTheTotalNumberNetworkDevicesBasedOnTheProvidedComplexFilters', E'Gets the total number Network Devices based on the provided complex filters and aggregation functions. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api-specs/blob/main/Assuran...\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getLayer3VirtualNetworks', E'Returns a list of layer 3 virtual networks that match the provided query parameters.\nParams: virtualNetworkName, fabricId, anchoredSiteId, offset, limit', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_deleteLayer3VirtualNetworks', E'Deletes layer 3 virtual networks based on user input.\nParams: virtualNetworkName', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_addLayer3VirtualNetworks', E'Adds layer 3 virtual networks based on user input.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updateLayer3VirtualNetworks', E'Updates layer 3 virtual networks based on user input.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_importCertificateP12', E'This API enables a user to import a PKCS12 certificate bundle for the controller and/or disaster recovery.\nParams: Content-Type (required), p12Password (required), pkPassword, listOfUsers', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getDetailsOfASingleNetworkDevice', E'API to fetch the details of network device using the `id`. Use the `/dna/intent/api/v1/networkDevices/query` API for advanced filtering. The API supports views to fetch only the required fields. Refer features for more details.\nParams: id (required), views', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_createsConfigurationDetailsOfTheExternalIPAMServer.', E'Creates configuration details of the external IPAM server. You should only create one external IPAM server; delete any existing external server before creating a new one.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_retrievesConfigurationDetailsOfTheExternalIPAMServer.', E'Retrieves configuration details of the external IPAM server.  If an external IPAM server has not been created, this resource will return a `404` response.', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_deletesConfigurationDetailsOfTheExternalIPAMServer.', E'Deletes configuration details of the external IPAM server.', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updatesConfigurationDetailsOfTheExternalIPAMServer.', E'Updates configuration details of the external IPAM server.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('retrievesTheCountOfProfilesThatTheGivenSiteHasBeenAssigned', E'Retrieves the count of profiles that the given site has been assigned.  These profiles may either be directly assigned to this site, or were assigned to a parent site and have been inherited.\nParams: siteId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
