INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_claimADeviceToASite', E'Claim a device based on Catalyst Center Site-based design process. Some required parameters differ based on device platform:\n\nDefault/StackSwitch: imageInfo, configInfo.  \n\nAccessPoints: rfProfile.  \n\nSensors: sensorProfile.  \n\nCatalystWLC/MobilityExpress/EWC: staticIP, subnetMask, gateway. vlanI...\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
