INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_downloadUnmasked(raw)DeviceConfigurationAsZIP', E'Download the unmasked (raw) device configuration by providing the file `id` and a `password`. The response will be a password-protected zip file containing the unmasked configuration. Password must contain a minimum of 8 characters, one lowercase letter, one uppercase letter, one number, one spec...\nParams: Content-Type (required), id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getTheDeviceDataForTheGivenDeviceId(Uuid)', E'Returns the device data for the given device Uuid in the specified start and end time range. When there is no start and end time specified returns the latest available data for the given Id. For detailed information about the usage of the API, please refer to the Open API specification document -...\nParams: id (required), startTime, endTime, view, attribute', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
