INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updatesTheMaintenanceScheduleInformation', E'API to update the maintenance schedule for the network devices. \nThe `maintenanceSchedule` can be updated only if the `status` value is `UPCOMING` or `IN_PROGRESS`. User can exit `IN_PROGRESS` maintenance window by setting the `endTime` to -1. This will update the endTime to the current time and ...\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_deleteMaintenanceSchedule.', E'API to delete maintenance schedule by id. Deletion is allowed if the maintenance window is in the `UPCOMING`, `COMPLETED`, or `FAILED` state. Deletion of maintenance schedule is not allowed if the maintenance window is currently `IN_PROGRESS`. To delete the maintenance schedule while it is `IN_PR...\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
