INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_readTransitNetworksCount', E'Get a count of transit networks. Use available query parameters to get the count of a subset of transit networks.\n\nThis API provides the latest health data until the given `endTime`. If data is not ready for the provided endTime, the request will fail with error code `400 Bad Request`, and the er...\nParams: X-CALLER-ID, startTime, endTime, id', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('retrieveTheCountOfNetworkDevicesThatAreAssociatedWithAtLeastOneT', E'Fetches the count of network devices that are associated with at least one tag. A tag is a user-defined or system-defined construct to group resources. When a device is tagged, it is called a member of the tag.', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_queryTheTagsAssociatedWithNetworkDevices.', E'Fetches the tags associated with the given network device `ids`. Devices that don''t have any tags associated will not be included in the response. A tag is a user-defined or system-defined construct to group resources. When a device is tagged, it is called a member of the tag. `ids` can be fetche...\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_inventoryInsightDeviceLinkMismatchAPI', E'Find all devices with link mismatch (speed /  vlan)\nParams: siteId (required), offset, limit, category (required), sortBy, order', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getTemplateVersionsCount', E'Get the count of a template''s version information.\nParams: templateId (required), versionNumber, latestVersion', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_systemLicensingStatus', E'Fetches registration status, authorization status and entitlements of the system with Cisco Smart Software Manage (CSSM).', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
