INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updateTemplateProject', E'Update a template project by the project''s ID.\nParams: Content-Type (required), projectId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
