INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_retrievesTheTotalCountOfThousandEyesTestResults', E'Retrieves the total count of ThousandEyes test results for the given filters. If `startTime` and `endTime` are not provided, the API defaults to the last 24 hours.  For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-...\nParams: X-CALLER-ID, siteId, startTime, endTime, testId, testName, testType, agentId', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getSiteAnalyticsForOneSite.', E'Returns site analytics for the given site. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api-specs/blob/main/Assurance/CE_Cat_Center_Org-SiteKpiSummaries-1.0.0-resolved.yaml\nParams: X-CALLER-ID, id (required), taskId, startTime, endTime, ssid, band, failureCategory', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_deleteSecurityServiceInsertion', E'Removes the Security Service Insertion (SSI) configuration from the fabric site where it was created.\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updateTheSecurityServiceInsertion.', E'Updates the Security Service Insertion (SSI). \nIt allows modifications to the associated Virtual Networks (VNs), border devices, and firewall ips.\nParams: Content-Type (required), id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
