INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_addFabricDevices', E'Adds fabric devices based on user input.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
