INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getsTheTop-NAnalyticsDataRelatedToNetworkDevices.', E'Gets the Top N analytics data related to network devices based on the provided input data. This endpoint is valuable to obtain the top-performing or most impacted network devices. For detailed information about the usage of the API, please refer to the Open API specification document - https://gi...\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
