INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_deletesAFloor', E'Deletes a floor from the network hierarchy. This operations fails if there are any devices assigned to this floor.\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
