INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getDevicesEnergy', E'Retrieves a list of network devices with energy data based on the specified query parameters. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api-specs/blob/main/Assurance/CE_Cat...\nParams: X-CALLER-ID, startTime, endTime, limit, cursor, sortBy, order, id', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getPowerProfilesCount', E'This API returns the total number of Power Profiles available.', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_deleteNFSConfiguration', E'This api is used to delete the NFS configuration.\nObtain the `id` from the id attribute in the response of the `/dna/system/api/v1/backupNfsConfigurations` API.\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
