INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updateInterfaceDetails', E'Add/Update Interface description, VLAN membership, Voice VLAN and change Interface admin status (''UP''/''DOWN'') from Request body.\nParams: Content-Type (required), interfaceUuid (required), deploymentMode', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_generateTheDeviceConfigForTheConfigurationModel.', E'Generates the device config for the configuration model. This API is ''Step 2'' in the following workflow -  Step 1- Use ''POST /intent/api/v1/wired/networkDevices/{networkDeviceId}/configFeatures/intended/configurationModels'' to start the provision of intended features. The response has a taskId wh...\nParams: Content-Type (required), networkDeviceId (required), previewActivityId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getsTheDeviceConfigForTheConfigurationModel.', E'Gets the device config for the configuration model. This API is ''Step 3'' in the following workflow. Step 1- Use ''POST /intent/api/v1/wired/networkDevices/{networkDeviceId}/configFeatures/intended/configurationModels'' to start the provision of intended features. The response has a taskId which is ...\nParams: networkDeviceId (required), previewActivityId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getCountOfBugsAffectingTheNetworkDevice', E'Get count of bugs affecting the network device\nParams: networkDeviceId (required), id, severity', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
