INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updateDot11axConfigurationFeatureTemplate', E'This API allows users to update the details of a specific Dot11ax configuration feature template by ID.\nParams: Content-Type (required), id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_deleteDot11axConfigurationFeatureTemplate', E'This API allows users to delete a specific Dot11ax configuration feature template by ID.\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getProject(s)Details', E'Get project(s) details\nParams: id, name, offset, limit, sortOrder', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_queryTheTagsAssociatedWithInterfaces.', E'Fetches the tags associated with the given interface `ids`. Interfaces that don''t have any tags associated will not be included in the response. A tag is a user-defined or system-defined construct to group resources. When an interface is tagged, it is called a member of the tag. `ids` can be fetc...\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('getTheTotalCustomIssueDefinitionsCountBasedOnTheProvidedFilters.', E'Get the total number of Custom issue definitions count based on the provided filters. The supported filters are id, name, profileId and definition enable status, severity, facility and mnemonic. For detailed information about the usage of the API, please refer to the Open API specification docume...\nParams: X-CALLER-ID, id, profileId, name, priority, isEnabled, severity, facility', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_legitOperationsForInterface', E'Get list of all properties & operations valid for an interface.\nParams: interfaceUuid (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getSiteTopology', E'Returns site topology', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_disableCBARFeatureOnMultipleNetworkDevices', E'This API can be used to disable CBAR feature on multiple network devices.\nRequest payload should include the list of network devices where it has to be disabled.\n\nThis operation pushes configuration to the network devices, and is only permitted if\nthe provisioning settings do not mandate a config...\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getDeviceConfigCount', E'Returns the count of device configs', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_retrievesSummaryOfNetworkDeviceLicenses', E'Retrieves the summary of consumed network, DNA, and Cisco Networking Subscription (CNS) licenses, along with the counts of unregistered and out-of-compliance network devices, and expired and expiring network device licenses.', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getSupervisorCardDetail', E'Get supervisor card detail for a given deviceuuid. Response will contain serial no, part no, switch no and slot no.\nParams: deviceUuid (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_setNTPSettingsForASite', E'Set NTP settings for a site; `null` values indicate that the setting will be inherited from the parent site; empty objects (`{}`) indicate that the settings is unset.\nParams: Content-Type (required), id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_retrieveNTPSettingsForASite', E'Retrieve NTP settings for a site; `null` values indicate that the setting will be inherited from the parent site; empty objects (`{}`) indicate that the setting is unset at a site.\nParams: id (required), _inherited', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
