INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_readListOfVirtualNetworksWithTheirHealthSummary', E'Get a paginated list of Virtual Networks with health summary. Layer 2 Virtual Networks are only included in health reporting for EVPN protocol deployments. The special Layer 3 VN called ‘INFRA_VN’ is also not included for user access through Assurance virtualNetworkHealthSummaries APIS. Please fi...\nParams: X-CALLER-ID, startTime, endTime, limit, offset, sortBy, order, id', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getConnectedDeviceDetail', E'Get connected device detail for given deviceUuid and interfaceUuid\nParams: deviceUuid (required), interfaceUuid (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updatesAnIPAddressSubpool.', E'Updates an IP address subpool, which reserves address space from a global pool (or global pools) for a particular site.\n\nRestrictions on updating an IP address subpool:\n- The `poolType` cannot be changed.\n- The `siteId` cannot be changed.\n- The `ipV4AddressSpace` may not be removed.\n- The `global...\nParams: Content-Type (required), id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_retrievesAnIPAddressSubpool.', E'Retrieves an IP address subpool, which reserves address space from a global pool (or global pools) for a particular site.\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_releaseAnIPAddressSubpool.', E'Releases an IP address subpool.\n\n**Release** completely removes the subpool from the site, and from all child sites, and frees the address use from the global pool(s).  Subpools cannot be released when assigned addresses in use.\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getTheDetailsOfIssuesForGivenSetOfFilters-2', E'Returns all details of each issue along with suggested actions for given set of filters specified in query parameters. If there is no start and/or end time, then end time will be defaulted to current time and start time will be defaulted to 24-hours ago from end time. All string type query parame...\nParams: Accept-Language, X-CALLER-ID, startTime, endTime, limit, offset, sortBy, order', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('getCountOfSecurityAdvisoryNetworkDevicesForTheSecurityAdvisory', E'Get count of security advisory network devices for the security advisory\nParams: id (required), networkDeviceId, scanMode, scanStatus', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('retrievesTheTrendAnalyticsRelatedToSpecificNetworkApplication.', E'Retrieves the trend analytics of applications experience data to specific network application for the specified time range. The data will be grouped based on the given trend time interval. This API facilitates obtaining consolidated insights into the performance and status of the network applicat...\nParams: Content-Type (required), X-CALLER-ID, id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_createTemplate', E'API to create a template by project id.\nParams: Content-Type (required), projectId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_authenticationAPI', E'API to obtain an access token, which remains valid for 1 hour. The token obtained using this API is required to be set as value to the X-Auth-Token HTTP Header for all API calls to Cisco DNA Center.\nParams: Content-Type (required), Authorization (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_mapsSupportedAccessPoints', E'Gets the list of supported access point types as well as valid antenna pattern names that can be used for each.', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getDevicesThatAreAssignedToASite', E'API to get devices that are assigned to a site.\nParams: id (required), offset, limit, memberType (required), level', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('getsInterfacesAlongWithStatisticsAndPoeDataFromAllNetworkDevices', E'Retrieves the list of the interfaces from all network devices based on\n        the provided query parameters. The latest interfaces data in the\n        specified start and end time range will be returned. When there is no\n        start and end time specified returns the latest available d...\nParams: startTime, endTime, limit, offset, sortBy, order, siteHierarchy, siteHierarchyId', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_applicationPolicyIntent', E'Create/Update/Delete application policy\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getListOfDiscoveriesByDiscoveryId', E'Returns the list of discovery jobs for the given Discovery ID. The results can be optionally filtered based on IP. Discovery ID can be obtained using the "Get Discoveries by range" API.\nParams: id (required), offset, limit, ipAddress', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getHealthScoreDefinitionForTheGivenId.', E'Get health score defintion for the given id. Definition includes all properties from HealthScoreDefinition schema by default. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api-...\nParams: X-CALLER-ID, id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updateHealthScoreDefinitionForTheGivenId.', E'Update health threshold, include status of overall health status.\n\nAnd also to synchronize with global profile issue thresholds of the definition for given id. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-pr...\nParams: Content-Type (required), X-CALLER-ID, id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_deleteANetworkDeviceWithoutConfigurationCleanup', E'This API endpoint facilitates the deletion of a network device without performing configuration cleanup on the device. To delete a device via API, you must have permission to provision the network device. Although the API operation does not change the device configuration, removing a device witho...\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getSummaryAnalyticsDataOfIssues', E'Gets the summary analytics data related to issues based on given filters and group by field. This data can be used to find issue counts grouped by different keys. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en...\nParams: Content-Type (required), Accept-Language, X-CALLER-ID', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_retrieveSitesWithOverriddenSSIDs', E'Retrieve list of siteId(s) with information of SSID(s) which are overridden\nParams: siteId, offset, limit', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('retrievesTheListOfDHCPServicesForGivenSetOfComplexFilters.', E'Retrieves the list of DHCP Services and offers complex filtering and sorting capabilities. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api-specs/blob/main/Assurance/CE_Cat_Ce...\nParams: Content-Type (required), X-CALLER-ID', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getTemplateVersions', E'Get a template''s version information.\nParams: templateId (required), versionNumber, latestVersion, order, limit, offset', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
