INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('retrieveACountOfTheNumberOfAssuranceTasksThatCurrentlyExist', E'returns a count of the number of assurance tasks that are not expired\nFor detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api-specs/blob/main/Assurance/CE_Cat_Center_Org-AssuranceTas...\nParams: X-CALLER-ID, status', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getAllHealthScoreDefinitionsForGivenFilters.', E'Get all health score defintions.\n\nSupported filters are id, name and overall health include status. A health score definition can be different across device type. So, deviceType in the query param is important and default is all device types.\n\nBy default all supported attributes are listed in res...\nParams: X-CALLER-ID, deviceType, id, includeForOverallHealth, attribute, offset, limit', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('theTrendAnalyticsDataForAVirtualNetworkInTheSpecifiedTimeRange', E'Get health time series for a specific Virtual Network by providing the unique Virtual Network id in the url path. Layer 2 Virtual Networks are only included in health reporting for EVPN protocol deployments. The special Layer 3 VN called ‘INFRA_VN’ is also not included for user access through As...\nParams: X-CALLER-ID, id (required), startTime, endTime, trendInterval (required), limit, offset, order', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getTemplate(s)Details', E'Get template(s) details\nParams: id, name, projectId, projectName, softwareType, softwareVersion, productFamily, productSeries', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_updateMulticast', E'Updates a multicast configuration at a fabric level based on user input.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getMulticast', E'Returns a list of multicast configurations at a fabric site level that match the provided query parameters.\nParams: fabricId, offset, limit', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getExternalAuthenticationServersAPI', E'Get external users authentication servers.\nParams: invokeSource (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_countClientsEnergy', E'Retrieves the total count of client devices that provide energy data, filtered according to the specified query parameters. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api-sp...\nParams: X-CALLER-ID, startTime, endTime, id, siteId, siteHierarchy, siteHierarchyId, deviceCategory', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_retrieveNetworkDevices', E'API to fetch the list of network devices using basic filters. Use the `/dna/intent/api/v1/networkDevices/query` API for advanced filtering. Refer features for more details. The API returns a paginated response based on ''limit'' and ''offset'' parameters, allowing up to 500 records per page. ''limit'' ...\nParams: id, managementAddress, serialNumber, family, stackDevice, role, status, reachabilityStatus', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_deleteApplicationSet', E'Delete existing custom application set by id\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
