INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_bulkDistributeImagesOnNetworkDevices', E'This API initiates the process of distributing the software image on the given network devices. Providing value for the `distributedImages` will only trigger the distribution process. To monitor the progress and completion of the update task, please call the GET API `/dna/intent/api/v1/networkDev...\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_resolveTheGivenListsOfIssues', E'Resolves the given list of issues. The response contains the list of issues which were successfully resolved as well as the issues which are failed to resolve. After this API returns success response, it may take few seconds for the issue status to be updated if the system is heavily loaded. Plea...\nParams: Content-Type (required), X-CALLER-ID', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_triggersAFieldNoticesScanForTheSupportedNetworkDevices', E'Triggers a field notices scan for the supported network devices. The supported devices are switches, routers and wireless controllers. If a device is not supported, the FieldNoticeNetworkDevice scanStatus will be Failed with appropriate comments. The consent to connect agreement must have been ac...\nParams: failedDevicesOnly', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
