INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_countTheNumberOfEventsWithFilters', E'API to fetch the count of assurance events for the given complex query. Please refer to the ''API Support Documentation'' section to understand which fields are supported. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/c...\nParams: Content-Type (required), X-CALLER-ID', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getDeviceConfigForAllDevices', E'Returns the config for all devices. This API has been deprecated and will not be available in a Cisco Catalyst Center release after Nov 1st 2024 23:59:59 GMT.', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
