INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getListOfChildEventsForTheGivenWirelessClientEvent', E'Wireless client event could have child events and this API can be used to fetch the same using parent event `id` as the input. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api...\nParams: X-CALLER-ID, id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
