INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_retrievesSummaryAnalyticsDataRelatedToClients.', E'Retrieves summary analytics data related to clients while applying complex filtering, aggregate functions, and grouping. This API facilitates obtaining consolidated insights into the performance and status of the clients. For detailed information about the usage of the API, please refer to the Op...\nParams: Content-Type (required), X-CALLER-ID', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_countOfNetworkDeviceImageUpdates', E'Returns the count of network device image updates based on the given filter criteria\nParams: id, parentId, networkDeviceId, status, imageName, hostName, managementAddress, startTime', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_claimDevice', E'Claims one of more devices with specified workflow\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_countTheNumberOfNetworkDevices', E'API to fetch the count of network devices using basic filters. Use the `/dna/intent/api/v1/networkDevices/query/count` API if you need advanced filtering.\nParams: id, managementAddress, serialNumber, family, stackDevice, role, status, reachabilityStatus', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_securityServiceInsertions.', E'Retrieves a list of all Security Service Insertions (SSIs) configured across fabric sites.\nParams: limit, offset, order, fabricSiteName', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_createSecurityServiceInsertionOnASpecificFabricSite.', E'Enables Security Service Insertion (SSI) on a fabric site within a network. \nSecurity Service Insertion allows the integration of security services, such as firewalls, \ninto the fabric network, ensuring that traffic within Virtual Networks (VNs) is routed \nthrough these security devices.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_readFabricSiteCount', E'Get a count of Fabric sites. Use available query parameters to get the count of a subset of fabric sites.\n\nThis API provides the latest health data until the given `endTime`. If data is not ready for the provided endTime, the request will fail with error code `400 Bad Request`, and the error mess...\nParams: X-CALLER-ID, startTime, endTime, id, siteHierarchy, siteHierarchyId', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_detachANetworkProfileFromADay-NCLITemplate', E'Detach a network profile from a Day-N CLI template by the profile ID and template ID.\nParams: templateId (required), profileId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
