INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getCountOfFieldNotices', E'Get count of field notices\nParams: id, deviceCount, type', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getFabricDevicesLayer3HandoffsWithIpTransitCount', E'Returns the count of layer 3 handoffs with ip transit of fabric devices that match the provided query parameters.\nParams: fabricId (required), networkDeviceId', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
