INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_retrievesTheCountOfREPRings.', E'This API returns the count of REP rings for the given fields - networkDeviceId (Network device ID of the REP ring member. The networkDeviceId is the instanceUuid attribute in the response of API - /dna/intent/api/v1/networkDevices) and deploymentMode (FABRIC/NON_FABRIC).\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
