INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_countOfCustomNetworkDeviceValidations', E'Count the number of network device validations.\nParams: productSeriesOrdinal, operationType, type', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
