INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_manageExternalAuthenticationSettingAPI', E'Enable or disable external authentication in the System.\n\nPlease find the Administrator Guide for your particular release from the list linked below and follow the steps required to enable external authentication before trying to do so from this API.\n\nhttps://www.cisco.com/c/en/us/support/cloud-s...\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_retrievesTheListOfDHCPServicesForGivenParameters.', E'Retrieves the list of DHCP Services and offers basic filtering and sorting capabilities. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api-specs/blob/main/Assurance/CE_Cat_Cent...\nParams: X-CALLER-ID, startTime, endTime, limit, offset, sortBy, order, serverIp', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getProvisionedDevicesCount', E'Returns the count of provisioned devices based on query parameters.\nParams: siteId', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
