INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_restoreBackup', E'This api is used to trigger restore workflow of a specific backup.\nObtain the `id` from the id attribute in the response of the `/dna/system/api/v1/backups` API.\nTo monitor the progress and completion of the backup deletion , please call `/dna/system/api/v1/backupRestoreExecutions/{id}` api , whe...\nParams: Content-Type (required), id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_readTrendAnalyticsDataForASpecificSiteInYourNetwork', E'Retrieves the time series information of health and issue data for a site specified by the path parameter. The data will be grouped based on the specified trend time interval.\nFor detailed information about the usage of the API, please refer to the Open API specification document - https://github...\nParams: X-CALLER-ID, id (required), startTime, endTime, trendInterval, limit, offset, timeSortOrder', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
