INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getBugAffectingTheNetworkDeviceByDeviceIdAndBugId', E'Get bug affecting the network device by device Id and bug id\nParams: networkDeviceId (required), id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
