INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('getTrendAnalyticsDataForAGivenDHCPServiceMatchingTheIdOfTheServi', E'Gets the trend analytics data related to a particular DHCP Service matching the id. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api-specs/blob/main/Assurance/CE_Cat_Center_Or...\nParams: Content-Type (required), X-CALLER-ID, id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
