INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getTheListOfCustomNetworkDeviceValidations', E'Fetches custom network device validations that run on the network device as part of the update workflow. This process verifies and assesses the configuration of the network devices.\nParams: productSeriesOrdinal, operationType, type, order, offset, limit', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_createCustomNetworkDeviceValidation', E'Custom network device validation refers to the tailored process of verifying and assessing the configurations of network devices based on specific organizational requirements and unique network environments. Unlike standard validations, custom network device validations are designed to address th...\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_retrievesTheTotalNumberOfAAAServicesForGivenParameters.', E'Retrieves the total number of AAA Services for given parameters. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api-specs/blob/main/Assurance/CE_Cat_Center_Org-AAAServices-1.0.0...\nParams: X-CALLER-ID, startTime, endTime, serverIp, deviceId, deviceName, deviceSiteHierarchy, deviceSiteHierarchyId', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_readListOfSiteHealthSummaries.', E'Get a paginated list of site health summaries. Use the available query parameters to identify a subset of sites you want health summaries for.\nThis API provides the latest health data from a given `endTime`\nIf data is not ready for the provided endTime, the request will fail, and the error messag...\nParams: X-CALLER-ID, startTime, endTime, limit, offset, sortBy, order, siteHierarchy', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
