INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getFieldNoticesAffectingTheNetworkDevice', E'Get field notices affecting the network device\nParams: networkDeviceId (required), id, type, offset, limit, sortBy, order', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getAPAuthorizationListByNetworkDeviceId', E'This API allows the user to get an AP Authorization List details configured for the given provisioned network device Id. Obtain the network device ID value by using the API GET call ''/dna/intent/api/v1/network-device/ip-address/${ipAddress}''.\nParams: networkDeviceId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('createsAICAPConfigurationWorkflowForICAPIntentToRemoveTheICAPCon', E'Creates a ICAP configuration intent to remove the ICAP RFSTATS or ANOMALY configuration from the device. The task has not been applied to the device yet. Subsequent preview-approve workflow APIs must be used to complete the preview-approve process.  The path parameter ''id'' can be retrieved from *...\nParams: Content-Type (required), id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('retrievesDeployedICAPConfigurationsWhileSupportingBasicFiltering', E'Retrieves deployed ICAP configurations while supporting basic filtering. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api-specs/blob/main/Assurance/CE_Cat_Center_Org-ICAP_APIs...\nParams: captureStatus (required), captureType, clientMac, apId, wlcId, offset, limit', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('getSiteAnalyticsForTheChildSitesOfGivenParentSiteAndOtherQueryPa', E'Returns site analytics for all child sites of given parent site. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api-specs/blob/main/Assurance/CE_Cat_Center_Org-SiteKpiSummaries-...\nParams: X-CALLER-ID, taskId, startTime, endTime, siteHierarchy, siteHierarchyId, siteId, siteType', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('getsTheNetworkDeviceDetailsBasedOnTheProvidedQueryParameters.', E'Gets the Network Device details based on the provided query parameters.  When there is no start and end time specified returns the latest device details. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programm...\nParams: startTime, endTime, limit, offset, sortBy, order, siteHierarchy, siteHierarchyId', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getTasks-2', E'Returns task(s) based on filter criteria\nParams: startTime, endTime, data, errorCode, serviceType, username, progress, isError', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
