INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('retrievesTheListOfClientsByApplyingComplexFiltersWhileAlsoSuppor', E'Retrieves the list of clients by applying complex filters while also supporting aggregate attributes. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api-specs/blob/main/Assuranc...\nParams: Content-Type (required), X-CALLER-ID', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
