INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_createRRMGeneralConfigurationFeatureTemplate', E'This API allows users to create a RRM General configuration feature template.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getModules', E'Returns modules by specified device id. The API returns a paginated response based on ''limit'' and ''offset'' parameters, allowing up to 500 records per page. ''limit'' specifies the number of records, and ''offset'' sets the starting point using 1-based indexing. Use /dna/intent/api/v1/network-device/m...\nParams: deviceId (required), limit, offset, nameList, vendorEquipmentTypeList, partNumberList, operationalStateCodeList', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_fetchNetworkDeviceWithImageDetails', E'The API retrieves information about running images and golden image bundle, if they are available for the network device. It also provides network device update status and image update status related to the golden image bundle and the compatible features supported by the network device. Network d...\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('retrievesTheListOfClients,WhileAlsoOfferingBasicFilteringAndSort', E'Retrieves the list of clients, while also offering basic filtering and sorting capabilities. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api-specs/blob/main/Assurance/CE_Cat_...\nParams: X-CALLER-ID, startTime, endTime, limit, offset, sortBy, order, type', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_systemLicensingRegistration', E'Registers the system with Cisco Smart Software Manager (CSSM)\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_retrieveAListOfAssuranceTasks', E'returns all existing tasks in a paginated list\n\ndefault sorting of list is `startTime`, `asc`\n\nvalid field to sort by are [`startTime`,`endTime`,`updateTime`,`status`]\nFor detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cis...\nParams: X-CALLER-ID, limit, offset, sortBy, order, status', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getRest/WebhookSubscriptionDetails', E'Gets the list of subscription details for specified connectorType\nParams: name, instanceId, offset, limit, sortBy, order', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getApplicationPolicyQueuingProfileCount', E'Get the number of all existing  application policy queuing profile', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_createSites', E'Create area/building/floor together in bulk. If site already exist, then that will be ignored. Sites in the request payload need not to be ordered.\nParams: Content-Type (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getSiteAssignedNetworkDevice', E'Get site assigned network device. The items in the list are arranged in an order that corresponds with their internal identifiers.\nParams: id (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('getsTheTotalNetworkDeviceCountsBasedOnTheProvidedQueryParameters', E'Gets the total Network device counts. When there is no start and end time specified returns the latest interfaces total count. For detailed information about the usage of the API, please refer to the Open API specification document - https://github.com/cisco-en-programmability/catalyst-center-api...\nParams: startTime, endTime, id, siteHierarchy, siteHierarchyId, siteId, managementIpAddress, macAddress', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
