INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_systemPerformanceAPI', E'Retrieves the aggregated metrics (total, average or maximum) of cluster key performance indicators (KPIs), such as CPU utilization, memory utilization or network rates recorded within a specified time period. The data will be available from the past 24 hours.\nParams: kpi, function, startTime, endTime', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
