INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getNetworkDeviceByPaginationRange', E'Returns the list of network devices for the given pagination range. The maximum number of records that can be retrieved is 500\nParams: startIndex (required), recordsToReturn (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_deploysTheICAPConfigurationIntentByActivityID.', E'Deploys the ICAP configuration intent by activity ID, which was returned in property "taskId" of the TaskResponse of the POST.  POST''ing the intent prior to generating the intent CLI for preview-approve has the same effect as direct-deploy''ing the intent to the device.\n\nGenerating of device''s CLI...\nParams: Content-Type (required), previewActivityId (required)', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getAllInterfaces', E'Returns all available interfaces. This endpoint can return a maximum of 500 interfaces. The API returns a paginated response based on ''limit'' and ''offset'' parameters, allowing up to 500 records per page. ''limit'' specifies the number of records, and ''offset'' sets the starting point using 1-based i...\nParams: offset, limit, lastInputTime, lastOutputTime', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
