INSERT INTO tool_description_overrides (operation_name, enhanced_description, is_active) VALUES ('intent_getDeviceValuesThatMatchFullyOrPartiallyAnAttribute', E'Returns the list of values of the first given required parameter. You can use the .* in any value to conduct a wildcard search.\nFor example, to get all the devices with the management IP address starting with 10.10. , issue the following request: GET /dna/intent/api/v1/network-device/autocomplete...\nParams: vrfName, managementIpAddress, hostname, macAddress, family, collectionStatus, collectionInterval, softwareVersion', true) ON CONFLICT (operation_name) DO UPDATE SET enhanced_description = EXCLUDED.enhanced_description, updated_at = NOW();
